def build():
 fs=[scene01,scene02,scene03,scene04,scene05,scene06,scene07,scene08,scene09,scene10,scene11,scene12,scene13,scene14,scene15]
 scenes=[]
 for i,((sid,title,route,note),render) in enumerate(zip(SCENES,fs),1):
  document=f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>{title} · Circuit design reference</title><link rel="stylesheet" href="styles.css"></head><body data-scene="{sid}">{render()}{notice_footer("Circuit / forge · M1 visual reference · Fictional products and account · Proposed controls require canonical integration")}<script src="interactions.js"></script></body></html>'
  (OUT/f'{sid}.html').write_text(document)
  scenes.append({'id':sid,'number':i,'title':title,'routeGroup':route,'note':note,'source':f'source/{sid}.html','images':{d:f'images/{sid}-{d}.png' for d in ['desktop','tablet','mobile']},'board':f'boards/{sid}.png'})
 # Consolidated route references keep one header/main/footer for home and PDP.
 import re
 for filename,title,body in [
  ('home-complete.html','Circuit complete homepage',header()+'<main>'+''.join(re.search(r'<main[^>]*>(.*?)</main>',f(),re.S).group(1) for f in [scene01,scene02])+'</main>'+footer()),
  ('product-complete.html','Circuit complete CG-7 PDP',header()+'<main>'+''.join('<section class="wrap section">'+re.search(r'<main[^>]*>(.*?)</main>',f(),re.S).group(1).replace(context(),'')+'</section>' for f in [scene04,scene05,scene06])+'</main>'+footer())
 ]:
  (OUT/filename).write_text(f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><link rel="stylesheet" href="styles.css"></head><body>{body}<script src="interactions.js"></script></body></html>')
 (ROOT/'scenes.json').write_text(json.dumps(scenes,indent=2)+'\n')
 (ROOT/'fixtures.json').write_text(json.dumps({'fictional':True,'site':'circuit.example.test','buyer':{'name':'Mira Rao','email':'mira@example.test','address':'24 Sample Lane, Flat 3B, Indiranagar, Bengaluru, Karnataka 560038, India'},'catalog':PRODUCTS,'cart':{'lines':[{'sku':'NW-CG7-GR','quantity':1,'unitPrice':3490},{'sku':'NW-CL100-1M-GR','quantity':1,'unitPrice':690}],'subtotal':4180,'shipping':80,'discount':0,'total':4260,'taxTreatment':'tax inclusive, no extra tax added'},'order':{'id':'CIR-1024','date':'2026-10-20','status':'confirmed','payment':'recorded mock fixture','fulfillment':'not yet dispatched'},'compatibility':{'cg7':{'merchantReference':'NW-CG7-F1','sourceDate':'2026-10-22','requirements':['USB-C data','DisplayPort Alt Mode for HDMI','USB-PD host input for charging'],'deviceModelStatus':'unconfirmed'},'normalizations':['5 Gb/s = 5000 Mb/s','0.10 m = 100 mm'],'incomparable':'CG-5 PD input 65 W cannot substitute for unknown laptop pass-through output'}},indent=2)+'\n')
 (ROOT/'prototype-index.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Circuit editable prototype</title><style>body{font:16px/1.6 Arial,sans-serif;max-width:900px;margin:40px auto;padding:0 24px;color:#142236}a{color:#17476e}li{margin:16px 0}</style><h1>Circuit responsive source</h1><p>Local visual references; proposed commerce controls make no network requests. <a href="source/home-complete.html">Complete homepage</a> · <a href="source/product-complete.html">Complete PDP</a>. Scenes 01–02 are one homepage; 04–06 are one PDP.</p><p><a href="index.html">Open image storybook</a> · <a href="comparisons/index.html">Research and neutral comparison</a></p><ol>'+''.join(f'<li><a href="{s["source"]}">{s["title"]}</a><br><small>{s["note"]}</small></li>' for s in scenes)+'</ol></html>')
 print('Built',len(scenes),'Circuit scenes')

if __name__=='__main__': build()
